FB_Conveyor.saved.declaration:
FUNCTION_BLOCK FB_Conveyor
VAR_INPUT
	bEnable : BOOL;
	bReset : BOOL;
END_VAR
VAR_OUTPUT
	bRunning : BOOL;
	bError : BOOL;
END_VAR
VAR
	nStep : INT;
	tonStart : TON;
END_VAR

FB_Conveyor.saved.implementation:
CASE nStep OF
	0:
		IF bEnable THEN
			nStep := 10;
		END_IF
	10:
		tonStart(IN := TRUE, PT := T#2S);
		IF tonStart.Q THEN
			bRunning := TRUE;
			nStep := 20;
		END_IF
	20:
		IF NOT bEnable THEN
			bRunning := FALSE;
			nStep := 0;
		END_IF
END_CASE

FB_Conveyor.snapshot.declaration:
FUNCTION_BLOCK FB_Conveyor
VAR_INPUT
	bEnable : BOOL;
	bReset : BOOL;
END_VAR
VAR_OUTPUT
	bRunning : BOOL;
	bError : BOOL;
END_VAR
VAR
	nStep : INT;
	tonStart : TON;
	tonWatch : TON;
END_VAR

FB_Conveyor.snapshot.implementation:
CASE nStep OF
	0:
		IF bEnable THEN
			nStep := 10;
		END_IF
	10:
		tonStart(IN := TRUE, PT := T#2S);
		IF tonStart.Q THEN
			bRunning := TRUE;
			nStep := 20;
		END_IF
	20:
		tonWatch(IN := bRunning, PT := T#30S);
		IF tonWatch.Q THEN
			bError := TRUE;
		END_IF
		IF NOT bEnable THEN
			bRunning := FALSE;
			nStep := 0;
		END_IF
END_CASE

FB_Axis.Start.implementation:
IF fVelocity <= 0 THEN
	Start := FALSE;
	RETURN;
END_IF
fSetVelocity := fVelocity;
bStartRequest := TRUE;
Start := TRUE;

PRG_Main.A_Reset.implementation:
fbConveyor(bEnable := FALSE, bReset := TRUE);
nAlarmCount := 0;
bAlarm := FALSE;
